@once
    @push('styles')
        <style>
            .catalog-seo-guide{margin-top:18px}.catalog-seo-guide__text{max-width:900px;margin:0 0 14px;color:var(--text-2);font-size:13px;line-height:1.55}.catalog-seo-guide__links{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}.catalog-seo-guide__links a{color:var(--text);font-size:12px;font-weight:650;text-decoration:underline;text-decoration-color:var(--line);text-underline-offset:4px}.catalog-seo-guide__links a:hover{text-decoration-color:var(--text)}@media(max-width:767px){.catalog-seo-guide{margin-top:14px}.catalog-seo-guide__text{padding:0 15px}.catalog-seo-guide__links{flex-wrap:nowrap;margin-right:0;margin-left:0;padding-right:15px;padding-left:15px;overflow-x:auto;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch;scroll-snap-type:x proximity;scrollbar-width:none}.catalog-seo-guide__links::-webkit-scrollbar{display:none}.catalog-seo-guide__links a{flex:0 0 auto;scroll-snap-align:start}.catalog-seo-guide .catalog-quick-filter__items{margin-top:0}}
        </style>
    @endpush
@endonce
